        "note": "日経平均は429.23円安の60,819.36円（−0.70%）と4日ぶりに反落した。前日の米国市場でNYダウが254ドル高と反発し、CoreWeaveの好決算でAI関連の投資意欲が支えられた流れを受けて東京市場は226円高で始まり、前場には一時61,788.44円まで500円超上昇した。ところが米ウォール・ストリート・ジャーナルがエヌビディアの取締役会がジェンスン・フアンCEOの解任準備を進めていると報じ、同社株が時間外取引で7.6%安の160.50ドルまで急落したことで半導体関連に売りが波及。後場は習近平主席の台湾関連発言を受けた台湾株急落や韓国KOSPIの反落、ナスダック先物の下げ拡大も重なり、安値60,643.79円まで売られた。寄与度はアドバンテストが−313.91円と1銘柄で指数の下げ幅の7割強を生み、リクルートホールディングス−100.12円、ソフトバンクグループ−94.66円、イビデン−77.67円、ファナック−25.11円を含む下位5銘柄で約611円を押し下げた。押し上げはコナミグループ+16.86円、KDDIと東京エレクトロンが各+16.18円、セコム+15.17円、JT+14.63円と上位5銘柄で約79円にとどまる。一方で内需・ディフェンシブへの資金シフトが進み、TOPIXは7.94ポイント高の3,937.33（+0.20%）と4日続伸、東証33業種中27業種が上昇し水産農林業・ゴム製品・食料品・陸運業・不動産業が上昇率上位となった。東証プライムの売買代金は概算9兆867億円、売買高は27億2,754万株、騰落は値上がり959・値下がり548で、指数は値がさ半導体株主導で下げながら中身は堅調という選別相場だった。東証グロース市場250指数は28.08ポイント安の729.65と4日ぶりに大幅反落し、グロース市場の騰落は値上がり187・値下がり374と値下がり優勢。為替は円安基調が続いた。ドル円は前日のNY市場で約2カ月ぶり高値の159.94円まで急伸した流れを引き継ぎ、東京時間は三村財務官の「ここ数日の動きは早すぎる印象」「夏の記憶を忘れるには早すぎる」との円安けん制発言で159.48円まで下押ししたが、日銀・浅田委員が長崎での講演で「利上げの経済への影響は従来より大きい」「消費はとくに強くない」と述べ12月会合での追加利上げに慎重な姿勢を示したことで159.80円台へ切り返した。当日レンジは159.48−159.94円。株式市場の大引け時点は159.69円で前日のNY終値比10銭の円高だが、前日午後5時時点比では約90銭の円安。レポート作成時点の17時は159.70−159.80円、18時台のロンドン序盤は159.95円まで上昇したのち159.60円台へ反落した。ユーロ円は176.80−177.29円のレンジで、大引け時点176.96円（前日NY終値比25銭の円高）、17時時点177.00−177.10円。円安が進んだ理由は、10月の米CPIが市場予想を上振れしたうえシカゴ連銀グールズビー総裁が「インフレは悪い方向に動いている」と発言し、ウォラー理事とローガン総裁が0.5%利上げの可能性に言及したことでFRBの追加利上げ観測が台頭し、米10年債利回りが一時5.0%台を回復して日米金利差拡大が意識されたこと。ドル指数は年初来高値圏まで上昇し、ユーロドルは年初来安値の1.1066ドルまで下落した。もっとも160円の節目では日米協調介入への警戒が強く、10月の国内企業物価指数が前月比+0.7%・前年同月比+7.1%と予想を上回ったことも円を支えた。円安は輸出関連の支えとなりホンダが2.40%高、ブリヂストンが3.97%高、ソニーグループが1.93%高と上昇したが、半導体・AI関連はエヌビディア報道が勝って為替の追い風を打ち消し、イビデンが8.32%安、ロームが7.41%安、太陽誘電が4.35%安、村田製作所が4.27%安と総崩れとなった。輸入比率の高い内需・小売はコスト高懸念が意識され、ファーストリテイリングが0.36%安、良品計画が2.13%安と重い。新発10年国債利回りは2.790%で横ばい。ストップ高は11銘柄、ストップ安は4銘柄（いずれも気配・一時ストップを含む株探基準）。"
