    "note": "日経平均は322円99銭高の6万1142円35銭と反発した。前日の米市場ではエヌビディアがジェンスン・フアンＣＥＯの退任を発表したことで半導体株が売られ、ＮＹダウは189ドル安、ナスダックは100ポイント安で引けたが、同社株が時間外取引で切り返したことから東京市場では売り方の買い戻しが先行し、前場には6万1902円50銭まで上げ幅を1,000円超に広げた。もっとも後場は週末を控えた利益確定売りと韓国ＫＯＳＰＩ安に押され、上げ幅の大半を削って引けている。寄与度ではファーストリテイリングが156円15銭、アドバンテストが134円84銭、リクルートＨＤが85円46銭と指数を押し上げた一方、ソフトバンクグループが154円53銭、テルモが42円61銭、イビデンが34円65銭の押し下げ要因となった。財務省が次期防衛力整備計画について5年間で50兆円台とする基準を防衛省に示したと伝わり、川崎重工業や三菱重工業など防衛関連が総崩れとなったのも重荷。ＴＯＰＩＸは4.24ポイント高の3,941.57。東証プライムの売買代金は8兆4,082億円で、値上がり875・値下がり618・変わらず52と上昇優勢だった。ストップ高は15銘柄、ストップ安は6銘柄。為替はドル円が東京市場で159円66銭〜160円19銭のレンジで推移した。ＦＲＢの追加利上げ観測と、ウィリアムズＮＹ連銀総裁の「インフレ率は高すぎる」との発言を受けて午後に160円の節目を上抜けたが、政府・日銀による介入警戒から159円66銭まで押し戻される荒い展開となった。株式市場の大引け近辺にあたる15時時点は159円96銭で、前日夕方（12日18時）の159円71銭に比べ25銭程度の円安。18時時点は159円91銭前後だった。ユーロ円は176円60銭〜177円13銭のレンジで、15時時点176円90銭、18時時点は176円85銭前後で推移している。もっとも本日は円安が輸出関連・半導体株を一様に押し上げる構図にはならず、アドバンテストや東京エレクトロンが買われる半面、キオクシアＨＤ、レーザーテック、イビデン、太陽誘電は下落してまちまちだった。業種別は33業種中19業種が上昇し、サービス業・小売業・倉庫運輸関連が上昇率上位、非鉄金属・機械・精密機器といった外需系が下落上位と、輸入比率の高い内需・小売が優位の「ねじれ」た構図となった。"
