        "outlook": "終値1,283円は買付価格1,284円との差がわずか1円まで縮まり、裁定目的の買いは一巡した。買付成立までは1,284円が上値のフタとなりやすく、監理銘柄指定・無配化・優待廃止も重なって値幅取りの余地は乏しい。対抗提案や買付価格の引き上げ観測が出るかが唯一の変動要因。"
