    "note": "日経平均は163円85銭高の5万9024円28銭と3営業日ぶりに反発した。前日の米国市場はシステム障害を受けたサイバー攻撃への警戒やエヌビディア決算を前にした持ち高調整、中東情勢に絡む原油高、ＦＲＢの追加利上げ観測から下落したが、取引終了後に発表されたエヌビディアの8〜10月期決算が売上高・純利益をほぼ倍増させ、11〜1月期の売上見通しも前年同期比約91%増と市場予想を上回ったことで同社株が時間外取引で上昇。東京市場では朝方からＡＩ・半導体関連に買い戻しが入り、日中は700円超上げる場面があった。もっとも上げ幅の大半を削る場面を経て、引けにかけて値がさ半導体株に支えられてプラス圏を維持する展開となった。寄与度ではアドバンテストが約255円、ソフトバンクグループと合わせた2銘柄で約338円を押し上げ、ＴＤＫ、東京エレクトロン、レーザーテック、村田製作所、バンダイナムコＨＤも指数を支えた一方、ファーストリテイリングが約110円の押し下げ要因となり、リクルートＨＤ、中外製薬、大塚ＨＤ、日東電工、豊田通商、信越化学が続いた。ただ内実は弱く、東証プライムの売買代金は8兆502億円、売買高は24億5,217万株で、値上がり401・値下がり1,110・変わらず40とプライムの約7割が下落。日経225構成銘柄でも79高・143安・3変わらずだった。ＴＯＰＩＸは16.02ポイント安の3,824.00と3日続落している。本日の相場を動かした最大の材料は情報漏えいの連鎖で、楽天証券の不正アクセスにより最大約447万口座の年収・金融資産を含む個人情報と、最大約1,125万口座の顧客コード・ログインＩＤが流出した可能性が判明し、楽天銀行が一時ストップ安、楽天グループは年初来安値を更新した。一方プレイドは主力「ＫＡＲＴＥ」への不正アクセスを受け、ジンズＨＤの1,829万件をはじめ顧客企業が相次いで漏えいを公表したことで2日連続の引けストップ安。その裏返しでサイバーセキュリティー関連が軒並み急騰し、ストップ高は7銘柄、ストップ安は4銘柄となった。業種別では石油・石炭製品、電気機器、海運業が上昇し、サービス業、空運業、陸運業が下落上位。為替はドル円が東京市場で159円12銭〜159円65銭のレンジで推移した。朝方はエヌビディア決算と日本株高を受けたリスクオンのドル買いで159円65銭まで上昇したが、米長期金利の低下と日経平均の失速を背景に159円10銭台まで押し戻された。株式市場の大引け近辺にあたる15時時点は159円27銭で前日比11銭程度の円高、18時時点も159円23銭前後と小動きだった。ユーロ円は174円62銭〜175円45銭のレンジで、15時時点は174円92銭と前日比37銭程度の円高、18時時点は174円58銭前後と円高が目立っている。12月ＦＯＭＣでの米追加利上げ観測がドルを支える一方、三村財務官と片山財務相の円安けん制発言による介入警戒が160円手前の上値を抑える構図で、植田日銀総裁が参院特別委員会で「政策金利の引き上げを続け、金融緩和の度合いを調整していくことが適切」と述べたことから12月会合での追加利上げ観測も根強い。もっとも本日の半導体株高はエヌビディア決算が主因で、円高下でもアドバンテストが4.56%高、レーザーテックが4.96%高、ＫＯＫＵＳＡＩ　ＥＬＥＣＴＲＩＣが5.86%高、村田製作所が4.10%高、太陽誘電が3.46%高と輸出・ハイテクが堅調だった。半面、円高メリットが意識されやすい輸入比率の高い内需・小売はイオンが4.06%安、良品計画が1.83%安、ファーストリテイリングが1.61%安と軟調で、為替が物色の手掛かりになる展開にはならなかった。"
