      "note": "日経平均は419円93銭高の5万9444円21銭と続伸した。前日の米市場ではエヌビディアが好決算を発表しながらも後継人事の不透明さと米当局の調査を嫌気して下落し、ＮＹダウは561ドル安と三日続落（ナスダック総合は5日ぶり反発）。もっとも東京市場では、米アンソロピックのナスダック上場に伴う公開価格が仮条件（70〜78ドル）の上限を上回る83ドルに決まったと伝わり、ＡＩ投資への過度な懸念が和らいだ。一時600円超高の5万9660円61銭まで上げた後、韓国ＫＯＳＰＩや台湾市場の下落で一時は5万8750円53銭まで沈んでマイナス圏に転じたものの、終盤にグレーマーケットでの同社株の好調な取引が報じられ、主力大型株主導で切り返した。寄与度ではソフトバンクグループが124円57銭、東京エレクトロンが121円86銭、コナミＧが38円43銭と指数を押し上げた一方、アドバンテストが32円36銭、豊田通商が25円08銭、三菱商事が15円07銭の押し下げ要因となり、半導体関連の中でも明確に強弱が分かれた。指数は上げたものの値下がり銘柄が全体の6割近くを占め、ＴＯＰＩＸは1.53ポイント安の3,822.47と四日続落。東証グロース250指数も675.02と六日続落した。東証プライムの売買代金は7兆7,190億円、値上がり599・値下がり897と下落優勢だった。業種別は33業種中15業種が上昇し、その他製品（+1.91%）・情報・通信業（+1.76%）・電気機器（+1.17%）が上昇率上位、海運業（−3.15%）・鉱業（−2.92%）・非鉄金属（−2.80%）・保険業（−2.20%）が下落上位。ＡＩ株の売り局面で逃避先となっていた銀行・鉄道などの内需株に巻き戻しの売りが出たことがＴＯＰＩＸの足を引っしった。ストップ高は7銘柄、ストップ安は3銘柄。為替はドル円が東京市場で159円28銭〜159円78銭のレンジで推移した。ＦＯＭＣ議事要旨でほぼ全参加者が12月の追加利上げの必要性で一致し、ウォラー理事が0.5%利上げに言及したことからドル買いが先行し、さらに植田日銀総裁が来年の春闘を「注視する」としてデフレ回帰リスクは「ある程度低下した」と述べたのが12月利上げ見送りと受け止められ、円売りを誘った。株式市場の大引け近辺にあたる15時時点は159円54銭で、前日夕方（18日17時）の159円34銭前後に比つ20銭程度の円安。夕方にかけてさらに上げ幅を広げ、17時時点は159円70〜80銭と前日高値を上抜けた。ユーロ円は174円72銭〜175円58銭のレンジで、15時時点174円96銭、17時時点は175円40〜50銭と円安ユーロ高が進んだ。ただし本日の株式市場を動かしたのは為替ではなくアンソロピックの公開価格で、円安にもかかわらず輸出関連・半導体株は東エレクが買われる半面でアドバンテストやイビデンが売られ、トヨタ自動車も軟調とまちまちだった。輸入比率の高い内需・小売株は、円安による仕入れコスト懸念よりも日本政府観光局が発表した10月の訪日客391万1,250人という単月過去最高を手がかりに買われ、Ｊフロントが3.3%高、ツルハＨＤが2.1%高と百貨店・ドラッグストアが優位だった。"
