      "note": "日経平均は2,207円98銭高の5万8,644円63銭と急反発した。前週末20日の3,007円安（下げ幅歴代5位）に対する反動と空売りの買い戻しが入り、寄り付きの5万7,009円99銭がそのまま当日の安値となり、日中は一時2,800円超上昇して5万9,262円57銭まで戻した。最大の材料は米エヌビディアがジェンスン・フアン氏をCEOに即時復帰させると決めたこと。ガバナンスの不透明感が後退して前日23日の米市場で同社株は30%超急騰し、NYダウは1,447ドル高の6日ぶり大幅反発、フィラデルフィア半導体株指数（SOX）は14%高となった。この流れを受けて東京市場でも半導体主力株が急騰し、寄与度上位はアドバンテスト（終値2万7,275円・12.5%高）、東京エレクトロン、ファーストリテイリング、ソフトバンクグループ、イビデンの5銘柄で合計約1,329円を押し上げた。一方で買いは半導体関連に偏り、内需株には売りも目立った。押し下げ寄与はKDDI（単独で約31円）、任天堂、伊藤忠商事、バンダイナムコＨＤ、セブン＆アイ・ホールディングスの5銘柄で合計約51円。ＴＯＰＩＸは90.66ポイント高の3,764.88。東証プライムの売買代金は8兆706億円、売買高は27億7,368万株で、値上がり956・値下がり558と上昇優勢。東証33業種中26業種が上昇し、非鉄金属・電気機器・ガラス土石製品が上昇率上位、鉱業・水産農林業・その他製品が下落率上位だった。ストップ高は12銘柄、ストップ安は1銘柄。為替はドル円が東京市場で158円75銭〜159円40銭のレンジ。午前は時間外の米10年債利回り低下を受けたドル売りで158円75銭まで下押ししたが、午後は日経平均が高値圏を維持し米株価指数先物も上げ幅を拡大したためリスクオンの円売りが優勢となり159円40銭まで切り返した。株式市場の大引け近辺にあたる15時40分時点は159円22銭（前営業日のＮＹ終値比20銭の円安、+0.13%）、日銀公表の午後5時時点は159円34〜36銭で前日比15銭のドル高・円安、18時時点は159円36銭前後。ユーロ円は173円27銭〜173円82銭のレンジで、大引け時点は173円68銭（同31銭の円安、+0.18%）、午後5時時点は173円77〜81銭と前日17時比では1円08銭のユーロ安・円高、18時は173円96銭前後まで円安に振れた。方向感が出にくい背景には、12月FOMCでの0.25%利上げ確率が95.8%と織り込まれる一方、日銀の12月会合での利上げ確率もOIS市場から計算して78.7%と高く、日米が同幅なら金利差が変わらない事情がある。ニューヨーク連銀のウィリアムズ総裁が「インフレ率は依然として高すぎる」と述べたこともドルを支えた。もっとも円の変動幅は0.1〜0.2%程度と小さく、当日の市況記事はいずれも株高の主因をエヌビディアのCEO復帰とSOX指数14%高に帰しており、円安が輸出関連・半導体株を押し上げたと明示した報道は確認できなかった。実際には株高が円売りを誘発する順方向で為替が動いており、輸入比率の高い内需・小売株では神戸物産が6.5%安となったが、これも10月度の月次営業利益が前年同月比7.8%減だったことが理由とされ、為替要因ではなかった。原油先物の下落（WTI2027年1月限80.17ドル、3.24ドル安）はコスト面で内需企業に追い風となる一方、鉱業セクターと石油関連株の売りにつながった。"
