      "note": "日経平均は487円54銭高の5万7,499円16銭と反発した。前日に1,633円安と急落した反動に加え、米エヌビディアやブロードコムが時間外取引で買われたことから主力の半導体関連株に買い戻しが入った。始値5万7,429円54銭から一時1,200円あまり上昇して高値5万8,251円93銭を付け5万8,000円台を回復したが、日銀の田村直樹審議委員の発言から追加利上げが意識されて前場中盤以降は伸び悩み、後場は「エヌビディアが製造パートナーに東南アジア4カ国へのサーバー出荷停止を伝えた」との海外報道が悪材料視されて上げ幅を縮め、安値5万7,288円10銭まで押す場面もあって5万8,000円台を終値では維持できなかった。米国が感謝祭で休場、翌日も短縮取引のため海外勢の売買は限定的で、リバランス・持ち高調整中心の商いだった。寄与度ではアドバンテストが約234円、ソフトバンクグループが約160円、キオクシアＨＤが約61円、ＴＤＫが約34円、東京エレクトロンが約23円と指数を押し上げ、上位5銘柄で約512円を稼いだ。マイナス側はファーストリテイリングの約54円を筆頭に、ダイキン工業の約18円、中外製薬の約12円、豊田通商の約12円、大塚ＨＤの約11円で、下位5銘柄の押し下げは約107円にとどまった。ＴＯＰＩＸは4.20ポイント高の3,750.40。東証プライムの売買代金は6兆8,287億円で、値上がり749・値下がり751・変わらず52とほぼ半々に分かれる指数主導の上昇だった。業種別は17業種が上昇し16業種が下落、非鉄金属・石油石炭製品・情報通信業・電気機器が上昇率上位で、空運業・食料品・医薬品・保険業が下落率上位。ストップ高は6銘柄、ストップ安は1銘柄。為替はドル円が東京市場で158円95銭〜159円26銭のレンジ。午前は前日の米ハイテク株警戒で米債が買われ10年債利回りが低下したことから日米金利差の縮小が意識され、9時50分過ぎに158円95銭まで円高が進んだが、午後は日経平均の上昇でリスク回避姿勢が後退して円売りが優勢となり、14時40分過ぎに159円20銭台を回復して高値159円26銭を付けた。株式市場の大引け近辺にあたる15時時点は159円16銭で前日午後5時比約5銭の円高ドル安、17時時点も159円16銭、18時10分時点は159円12〜20銭とやや失速した。ユーロ円は174円37銭〜174円76銭のレンジで、15時時点は174円45銭と前日比30銭強の円安ユーロ高、17時時点は174円65銭。前日発表の米PCE価格指数が前年比で予想を上回って加速したことから12月の追加利上げ観測がドルの下値を支える一方、160円が視野に入り日米協調介入への警戒も意識された。田村委員の記者会見に為替市場はほとんど反応しなかった。半導体・輸出関連ではキオクシアＨＤが12.57%高、アドバンテストが4.57%高、太陽誘電が4.36%高、レーザーテックが4.18%高と買われたが、各市況記事が挙げる主因は米ハイテク株の買い戻しで、円安を理由に挙げた記述はなく、ソニーＧが1.44%安、豊田通商が2.01%安と逆行安の輸出株もあった。輸入比率の高い内需側は食料品が業種別下落率上位でアサヒＧＨＤが2.45%安、キッコーマンが1.81%安、小売ではファーストリテイリングが0.78%安と指数最大のマイナス寄与になったが、これらは前日に買われたディフェンシブ銘柄への売りと説明されており、円安によるコスト増との明示的な関連づけはなかった。円安を業績の押し上げ要因として明示したのは児玉化学工業で、円安効果と一部製品のスポット需要を理由に通期を上方修正し、8日ぶりに急反発して一時ストップ高となった。"
